using System;

namespace Crashverse.Data
{
    // JSON-serialisable content models (Unity JsonUtility: public fields, [Serializable], no dictionaries).
    // Source of truth: design/Design_Pack_v1_Ch1_Powerups_LiveOps.md; generated by Tools/ContentGen/gen_content.py.

    [Serializable] public class Reward { public string type; public int amount; public string id; }

    [Serializable] public class MasteryGoal { public string type; public float value; public string role; public string text; }

    [Serializable] public class SlotRule { public string slot; public string powerup; }

    [Serializable]
    public class RuleModifiers
    {
        public float steelJointMult, woodHpMult, brickHpMult, steelHpMult, gravityScale; // 0 = unchanged
        public int shotDelta;
        public static float M(float v) => v <= 0f ? 1f : v;
    }

    [Serializable]
    public class LevelEntry
    {
        public string id; public int number; public string island; public string name; public string layout;
        public string objective; public int shots; public float winThreshold; public string[] materials;
        public string teaches; public MasteryGoal mastery; public SlotRule[] forced; public string[] lockedSlots;
        public string requires; public string bossId; public Reward[] reward;
        public float star3Pct = 0.60f; public float star2Pct = 0.30f; public int starCapIfPowerupUsed = 3; public float islandKillY = -2f; // SG-21
        public string hintTarget; public float hintYaw; public float hintPitch; // Addendum v1.1 §1
        public bool HasHint => !string.IsNullOrEmpty(hintTarget);
        public bool IsBoss => !string.IsNullOrEmpty(bossId);
    }

    [Serializable] public class IslandData { public string id; public string name; public float[] pos; public string gateAfterLevel; }

    [Serializable]
    public class ChapterData
    {
        public string id; public string name; public string nextRegion;
        public IslandData[] islands; public LevelEntry[] levels;
    }

    [Serializable]
    public class BlockData
    {
        public string id; public string mat; public float[] p; public float[] s; public string[] sup;
        public bool joint; public string role; public bool nonObj; public string color; public bool explosive;
        public bool indestructible; public float[] spinAxis; public float[] pivot; public float spinDps;
    }

    [Serializable] public class LayoutData { public string id; public BlockData[] blocks; }

    [Serializable]
    public class PowerUpParams
    {
        public float damage; public int linkDepth; public int count; public float damageMult; public float radius;
        public float duration; public float burstDamage; public int passCount; public float slowFactor;
    }

    [Serializable]
    public class PowerUpData
    {
        public string id; public string name; public string slot; public string effect; public int charges;
        public string unlockType; public string unlockLevelId; public string unlockText; public PowerUpParams p;
    }

    [Serializable] public class PowerUpCatalog { public PowerUpData[] powerups; }

    [Serializable] public class TitanArena { public string id; public string name; public string layout; public string hintTarget; public float hintYaw, hintPitch; }
    [Serializable] public class TitanRule { public string id; public string text; public RuleModifiers mod; }

    [Serializable]
